  const stream = { getTracks: () => [track] } as unknown as MediaStream;
  const uploader = {
    async start(_grant: typeof grant, _stream: MediaStream) {
      events.push("upload.start");
    },
    async finish() {
      events.push("upload.finish");
    },
    cancel() {
      events.push("upload.cancel");
    },
  };
  const mediaDevices = {
    async getUserMedia() {
